function videoList(id){const vs=MESSER_VIDEOS[id]||[];state.videos??={};return `<section class="card video-course"><div class="kicker">MESSER VIDEO SEQUENCE · ${id}</div><h2>Watch in this order</h2><p>Open the exact video, then mark it watched when you return. Videos require internet; lessons and progress work offline.</p>${vs.map((v,n)=>`<div class="video-row"><input type="checkbox" data-video="${esc(v.url)}" aria-label="Mark ${esc(v.title)} watched" ${state.videos[v.url]?'checked':''}><a href="${esc(v.url)}" target="_blank" rel="noopener">${n+1}. ${esc(v.title)} <small>${esc(v.duration)} ↗</small></a></div>`).join('')}<div class="btn-row"><button class="btn primary" id="nextVideo">Open next unwatched video</button><button class="btn secondary" id="nextObjective">Next objective →</button></div></section>`}
function bindVideos(id){document.querySelectorAll('[data-video]').forEach(x=>x.onchange=()=>{state.videos[x.dataset.video]=x.checked;save()});$('#nextVideo').onclick=()=>{const vs=MESSER_VIDEOS[id]||[],v=vs.find(v=>!state.videos[v.url]);if(v)window.open(v.url,'_blank','noopener');else toast('All videos in this objective are marked watched. Continue to the next objective.')};$('#nextObjective').onclick=()=>{const n=C.objectives.findIndex(o=>o.id===id)+1;if(n<C.objectives.length)openObjective(C.objectives[n].id);else toast('You reached the final objective.')};}
function backup(){title('Backup & Install','Keep your progress portable and make the app available offline');$('#content').innerHTML=`<div class="grid two">${card('Progress backup',`<p>Export your objective status, notes, attempts, PBQ drafts, and current exam. Merge adds missing history without replacing newer device values. Replace restores the selected backup exactly. Your personal backup should stay off the public website.</p>${button('Export backup','export','primary')}<label for="importMode">Import mode</label><select class="select" id="importMode"><option value="merge">Merge — keep existing device values</option><option value="replace">Replace — restore backup exactly</option></select><label class="file-label">Import Security+ backup<input type="file" id="importFile" accept="application/json,.json"></label><div id="importStatus" role="status"></div>`)}${card('iPad home screen',`<ol class="steps"><li>Open the published HTTPS app in Safari while online.</li><li>Wait for the offline status below to show ready.</li><li>Use Share → Add to Home Screen.</li><li>Open it once from its home-screen icon while online, then test in airplane mode.</li></ol><p id="offlineStatus">Checking offline cache…</p><p>Progress belongs to this browser and installation. Export before clearing website data or changing devices.</p>`)}</div>`;bind({export:()=>{const blob=new Blob([JSON.stringify({app:'security-plus-school',version:4,exported:new Date().toISOString(),state,messerExams:JSON.parse(localStorage.getItem('security-plus-messer-v1')||'null')},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='security-plus-study-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}});$('#importFile').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>20*1024*1024)throw Error('Backup is too large.');const j=JSON.parse(await f.text());if(j.app!=='security-plus-school'||j.version!==4||j.state?.version!==4||!Array.isArray(j.state.history)||!j.state.objectives||!j.state.labs)throw Error('Choose a valid Security+ School v4 backup. Network+ backups are separate.');const merge=$('#importMode').value==='merge';if(!confirm(merge?'Merge this backup? Existing device values stay; missing attempts and progress are added.':'Replace current Security+ progress with this backup? Export first if you need the current copy.'))return;state=merge?SCHOOL.merge(state,j.state,MESSER_VIDEOS):SCHOOL.migrate(j.state,MESSER_VIDEOS);if(j.messerExams?.version===1&&Array.isArray(j.messerExams.history)){let m=j.messerExams;if(merge){const local=JSON.parse(localStorage.getItem('security-plus-messer-v1')||'null');if(local?.version===1&&Array.isArray(local.history)){const ids=new Set(local.history.map(h=>h.id));m={...local,active:local.active||m.active,history:[...local.history,...m.history.filter(h=>!ids.has(h.id))].sort((a,b)=>b.finished-a.finished)}}}localStorage.setItem('security-plus-messer-v1',JSON.stringify(m))}save();go('dashboard');toast('Backup imported')}catch(err){$('#importStatus').textContent=err.message}};if('serviceWorker'in navigator)navigator.serviceWorker.ready.then(async()=>{const ready=await caches.has('security-plus-school-v13');if($('#offlineStatus'))$('#offlineStatus').textContent=ready?'Offline app cache ready. Videos and external references still require internet.':'Cache is not ready. Reload once online.'});else $('#offlineStatus').textContent='Offline installation requires HTTPS or localhost and service-worker support.'}
function showModal(t,body){$('#modal').classList.remove('lab-modal','show-lab-results');$('#modal').style.height='';lastFocus=document.activeElement;$('#modal').innerHTML=`<div class="modal-head"><h2 class="modal-title">${esc(t)}</h2><button class="close-btn" id="closeModal" aria-label="Close dialog">×</button></div><div class="modal-body">${body}</div>`;$('#modalBackdrop').hidden=false;document.body.style.overflow='hidden';$('#closeModal').onclick=closeModal;$('#modal').scrollTop=0;$('#closeModal').focus()}
function closeModal(){if(labResize){window.visualViewport?.removeEventListener('resize',labResize);labResize=null}$('#modal').style.height='';if($('#modalBackdrop').hidden)return;$('#modalBackdrop').hidden=true;document.body.style.overflow='';$('#modal').innerHTML='';examLab=null;if(page==='learn'||page==='dashboard')render();lastFocus?.focus?.()}
document.addEventListener('keydown',e=>{if($('#modalBackdrop').hidden)return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){const els=[...$('#modal').querySelectorAll('button,input,select,textarea,a,summary')].filter(x=>!x.disabled&&x.offsetParent!==null);if(!els.length)return;if(e.shiftKey&&document.activeElement===els[0]){e.preventDefault();els.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===els.at(-1)){e.preventDefault();els[0].focus()}}});$('#menuBtn').onclick=()=>$('#sidebar').classList.toggle('open');
let hadController=!!navigator.serviceWorker?.controller;if('serviceWorker'in navigator){navigator.serviceWorker.addEventListener('controllerchange',()=>{if(hadController&&!sessionStorage.getItem('security-plus-reloading')){sessionStorage.setItem('security-plus-reloading','1');location.reload()}hadController=true});window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').then(r=>{r.update();sessionStorage.removeItem('security-plus-reloading')}).catch(()=>toast('Offline cache could not be installed. Open over HTTPS.')));document.addEventListener('visibilitychange',()=>{if(!document.hidden)navigator.serviceWorker.getRegistration().then(r=>r?.update())})}
